# Austrian side choices (the side is a separate part; the bare dish asks).
SCHNITZEL_SIDES = [("erdaepfelsalat", 200), ("petrezselymes_burgonya", 200), ("hasabburgonya", 170), ("parolt_rizs", 180)]


def schnitzel_sides(*names):
    d = {}
    for n in names:
        d[f"{n} mit erdäpfelsalat"] = "erdaepfelsalat"
        d[f"{n} mit kartoffelsalat"] = "erdaepfelsalat"
        d[f"{n} mit petersilerdäpfeln"] = "petrezselymes_burgonya"
        d[f"{n} mit petersilkartoffeln"] = "petrezselymes_burgonya"
        d[f"{n} mit pommes"] = "hasabburgonya"
        d[f"{n} mit pommes frites"] = "hasabburgonya"
        d[f"{n} mit reis"] = "parolt_rizs"
    return d


def D(id, category, parts, served_in, tags, aliases, countries=("AT",), **kw):
    if kw.get("alias_side"):
        kw.setdefault("alias_side_locale", "de-AT")
    return dict(id=id, countries=list(countries), category=category, part_refs=parts, served_in=served_in, tags=tags, aliases=aliases, **kw)


